// allocator: lightweight compaction pass
void PerShardArena::compact_if_needed() {
  if (fragmentation_ratio() <= config_.compaction_threshold) return;
  // allocate temporary contiguous arena then copy-live-objects
  TempArena tmp(size_estimate());
  for (auto &obj : live_objects()) copy_to(tmp, obj);
  std::lock_guard g(shard_lock_);
  swap(arena_, tmp);
}
